/**
 * `juspay checkout agent-setup` — and its `uninstall` / `list` sub-commands.
 *
 * This is the original setup flow (formerly the default `npx @juspay/cli`),
 * unchanged in behavior: detect AI
 * agents → pick which + scope → write the Juspay MCP URLs → install the jp-* skills.
 * The flow logic lives in features/agent-setup/*; this module is the command-tree
 * wiring + the human-facing summary/next-steps output.
 */

import { spawn } from "node:child_process"

import type { Command } from "commander"
import pc from "picocolors"

import type { CliContext } from "../../../cli/types.js"
import { EXIT_PARTIAL } from "../../../core/errors.js"
import { AGENTS, hasOurMcp, type AgentDef } from "../../../shared/agents/index.js"
import { removeMcp } from "../features/agent-setup/mcp-writer.js"
import { runSetup, type SetupResult } from "../features/agent-setup/setup.js"
import { OUR_SKILL_NAMES, removeSkills } from "../features/agent-setup/skills-installer.js"

// The full command path, used in next-step hints so the printed commands match
// what the user actually types.
const CMD_PATH = "juspay checkout agent-setup"

export function registerAgentSetup(parent: Command, ctx: CliContext): void {
  const cmd = parent
    .command("agent-setup")
    .description("Add the Juspay MCP servers + integration skills to your AI coding agents")
    .action(() => runSetupCommand(ctx))

  cmd
    .command("uninstall")
    .description("Remove the Juspay MCP + skills (both scopes) and sign out")
    .action(() => runUninstall(ctx))

  cmd
    .command("list")
    .description("Show which agents have the Juspay MCP, and at which scope")
    .action(() => runList(ctx))
}

async function runSetupCommand(ctx: CliContext): Promise<void> {
  ctx.ui.banner()
  const result = await runSetup()
  if (result.configured.length > 0) {
    printSetupSummary(ctx, result)
  } else if (result.attempted > 0) {
    // User picked agents but every MCP write failed — make sure the failure is
    // loud (per-agent errors were info()-level above, easy to miss).
    ctx.ui.warn("No agents were configured — every write failed. See errors above.")
  }
  const partial = (result.attempted > 0 && result.configured.length === 0) || !result.skillsInstalled
  if (partial) process.exit(EXIT_PARTIAL)
}

// Print next steps: agents that still need a one-time manual auth. Already-authed
// / already-configured agents are not nagged.
function nextSteps(ctx: CliContext, result: SetupResult): void {
  process.stdout.write("\n  " + pc.bold("Next steps") + "\n")
  if (result.pending.length > 0) {
    process.stdout.write("  Authenticate the dashboard MCP — one-time, per agent:\n")
    for (const a of result.pending) {
      process.stdout.write("    " + pc.cyan("•") + " " + pc.bold(a.label) + pc.dim(" — ") + pc.cyan(a.authHint) + "\n")
    }
    process.stdout.write("  " + pc.dim("(the docs MCP needs no sign-in)") + "\n")
  } else {
    process.stdout.write("  " + pc.green("✓ ") + "All set — your agents are configured.\n")
  }
  process.stdout.write("\n  " + pc.dim("Remove everything: ") + pc.cyan(`${CMD_PATH} uninstall`) + "\n\n")
}

function printSetupSummary(ctx: CliContext, result: SetupResult): void {
  // Skills row mirrors the actual install state, so the box title and any
  // mid-output warning never contradict each other.
  const skillsValue = result.skillsInstalled
    ? OUR_SKILL_NAMES.join(", ")
    : pc.red(`failed — ${result.skillsError ?? "see errors above"}`)
  const rows: { label: string; value: string }[] = [
    { label: "Agents", value: result.configured.map((a) => a.label).join(", ") },
    { label: "Scope", value: result.scope === "global" ? "Global (all projects)" : "This project" },
    { label: "MCPs", value: "docs-mcp-server, juspay-mcp" },
    { label: "Skills", value: skillsValue },
  ]
  const title = result.skillsInstalled ? "Setup complete" : "Setup partial — skills not installed"
  ctx.ui.summaryBox(title, rows)
  nextSteps(ctx, result)
}

async function runUninstall(ctx: CliContext): Promise<void> {
  ctx.ui.banner()
  const removedAgents: AgentDef[] = []
  for (const a of AGENTS) {
    let removedAny = false
    for (const scope of ["global", "project"] as const) {
      if (await removeMcp(a, scope).catch(() => false)) removedAny = true
    }
    if (removedAny) removedAgents.push(a)
  }
  if (removedAgents.length > 0) {
    ctx.ui.done(`Removed Juspay MCP from: ${removedAgents.map((a) => a.label).join(", ")}`)
  } else {
    ctx.ui.info("• No Juspay MCP entries found")
  }

  // Sign out of agents that cache OAuth creds (best-effort; clears their tokens).
  const loggedOut: string[] = []
  for (const a of removedAgents) {
    if (!a.logoutCmd) continue
    if (await runCmdQuiet(a.logoutCmd)) loggedOut.push(a.label)
  }
  if (loggedOut.length > 0) ctx.ui.done(`Signed out of: ${loggedOut.join(", ")}`)

  if (await removeSkills()) ctx.ui.done("Removed Juspay skills")
  else ctx.ui.info(`• Skills not auto-removed — remove ${OUR_SKILL_NAMES.join(", ")} from your agents if needed`)

  process.stdout.write("\n  " + pc.cyan("Juspay removed.") + "\n\n")
}

// Run a command silently, best-effort. Resolves true on exit 0, false otherwise.
function runCmdQuiet(cmd: string[]): Promise<boolean> {
  return new Promise((resolve) => {
    const [bin, ...args] = cmd
    // Windows: agent CLIs are .cmd shims; spawn needs a shell to launch them.
    const child = spawn(bin, args, { stdio: "ignore", shell: process.platform === "win32" })
    child.on("error", () => resolve(false))
    child.on("exit", (code) => resolve(code === 0))
  })
}

async function runList(ctx: CliContext): Promise<void> {
  ctx.ui.banner()
  const found: string[] = []
  for (const a of AGENTS) {
    const scopes: string[] = []
    for (const scope of ["global", "project"] as const) {
      if (await hasOurMcp(a, scope)) scopes.push(scope)
    }
    if (scopes.length > 0) found.push(`${a.label} (${scopes.join(", ")})`)
  }
  if (found.length === 0) {
    process.stdout.write("  " + pc.yellow("⚠ ") + `No agents configured. Run \`${CMD_PATH}\`.\n`)
    return
  }
  process.stdout.write("  " + pc.cyan("Juspay MCP is configured in:") + "\n")
  for (const label of found) process.stdout.write(`    • ${label}\n`)
}

/**
 * One-shot streamable-HTTP MCP tool call. Ported verbatim from
 * juspay-skills/claude-cli/src/mcp-call.ts (constants now come from ./constants).
 *
 * Performs initialize → tools/call against `endpoint`, returns the tool result.
 * Used by `whoami` to read merchant details right after OAuth.
 */

import { CLI_VERSION, USER_AGENT } from "./constants.js"

type JsonRpcOk = { jsonrpc: "2.0"; id: number | string; result: any }
type JsonRpcErr = { jsonrpc: "2.0"; id: number | string; error: { code: number; message: string } }
type JsonRpcResponse = JsonRpcOk | JsonRpcErr

export async function callMcpTool(
  endpoint: string,
  bearer: string,
  tool: string,
  args: Record<string, unknown> = {},
): Promise<any> {
  let sessionId: string | undefined

  const initResult = await rpc(endpoint, bearer, sessionId, {
    jsonrpc: "2.0",
    id: 1,
    method: "initialize",
    params: {
      protocolVersion: "2025-06-18",
      capabilities: {},
      clientInfo: { name: "juspay-cli", version: CLI_VERSION },
    },
  })
  sessionId = initResult.sessionId

  if ("error" in initResult.body) {
    throw new Error(`MCP initialize failed: ${initResult.body.error.message}`)
  }

  await postNotification(endpoint, bearer, sessionId, {
    jsonrpc: "2.0",
    method: "notifications/initialized",
  })

  const callResult = await rpc(endpoint, bearer, sessionId, {
    jsonrpc: "2.0",
    id: 2,
    method: "tools/call",
    params: { name: tool, arguments: args },
  })

  if ("error" in callResult.body) {
    throw new Error(`MCP tool '${tool}' failed: ${callResult.body.error.message}`)
  }
  return callResult.body.result
}

async function rpc(
  endpoint: string,
  bearer: string,
  sessionId: string | undefined,
  payload: object,
): Promise<{ body: JsonRpcResponse; sessionId?: string }> {
  const res = await fetch(endpoint, {
    method: "POST",
    headers: buildHeaders(bearer, sessionId),
    body: JSON.stringify(payload),
  })
  if (!res.ok) {
    const text = await res.text().catch(() => "")
    throw new Error(`MCP HTTP ${res.status}: ${text.slice(0, 400)}`)
  }
  const sid = res.headers.get("mcp-session-id") ?? sessionId
  const body = await readJsonRpc(res)
  return { body, sessionId: sid ?? undefined }
}

async function postNotification(
  endpoint: string,
  bearer: string,
  sessionId: string | undefined,
  payload: object,
): Promise<void> {
  // Notifications don't expect a response body. Some servers still return 202 — that's fine.
  await fetch(endpoint, {
    method: "POST",
    headers: buildHeaders(bearer, sessionId),
    body: JSON.stringify(payload),
  })
}

function buildHeaders(bearer: string, sessionId?: string): Record<string, string> {
  const h: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    Authorization: `Bearer ${bearer}`,
    "User-Agent": USER_AGENT,
  }
  if (sessionId) h["Mcp-Session-Id"] = sessionId
  return h
}

async function readJsonRpc(res: Response): Promise<JsonRpcResponse> {
  const ct = res.headers.get("content-type") ?? ""
  const text = await res.text()
  if (ct.includes("text/event-stream")) {
    // Extract the first JSON-RPC payload from a `data: ` line.
    for (const line of text.split(/\r?\n/)) {
      if (line.startsWith("data:")) {
        const json = line.slice(5).trim()
        if (json) return JSON.parse(json) as JsonRpcResponse
      }
    }
    throw new Error("SSE response contained no JSON-RPC payload.")
  }
  return JSON.parse(text) as JsonRpcResponse
}

/**
 * Setup flow: detect agents → user PICKS which → user PICKS scope (global or
 * this project) → for each picked agent write the Juspay MCP URL at that scope
 * and install its skill at that scope.
 *
 * We do NOT authenticate — each agent authenticates the dashboard server itself
 * (in-app, or guided by the installed skill). No OAuth/token on our side.
 *
 * Idempotent: `pending` (agents we show auth hints for) is only the freshly-added
 * ones, so re-running setup doesn't re-nag already-configured agents.
 */

import { cancel, isCancel, multiselect, select } from "@clack/prompts"

import { detectAgents, hasOurMcp, type AgentDef, type Scope } from "../../../../shared/agents/index.js"
import { emitSetupStage, writeMcp } from "./mcp-writer.js"
import { addSkills } from "./skills-installer.js"
import { hint, info, spin, step, warn } from "../../../../core/ui.js"

export type SetupResult = {
  configured: AgentDef[]
  pending: AgentDef[]
  scope: Scope
  // How many agents the user picked. Lets `main` distinguish "user picked 0"
  // (return 0) from "user picked N but every write failed" (return 2).
  attempted: number
  // True if we never attempted skill install OR attempted and succeeded.
  // False ONLY when an attempt failed — that's what flips the summary box.
  skillsInstalled: boolean
  skillsError?: string
}

export async function runSetup(): Promise<SetupResult> {
  const detected = await detectAgents()
  if (detected.length === 0) {
    warn("No supported AI agents detected on this machine.")
    info("Install one (claude, codex, gemini, opencode, copilot, cursor, windsurf) and re-run.")
    return { configured: [], pending: [], scope: "global", attempted: 0, skillsInstalled: true }
  }

  const interactive = Boolean(process.stdin.isTTY && process.stdout.isTTY)
  const selected = await pickAgents(detected, interactive)
  if (selected.length === 0) {
    cancel("No agents selected.")
    process.exit(0)
  }
  const scope = await pickScope(interactive)

  // Some agents only work at user scope (Copilot / VS Code don't pick up
  // project-level config) — force those to global regardless of the chosen scope.
  const scopeFor = (a: AgentDef): Scope => (a.globalOnly ? "global" : scope)

  // 1. MCP config (idempotent merge). Track freshly-added so re-runs don't re-nag.
  const configured: AgentDef[] = []
  const pending: AgentDef[] = []
  const s = spin(`Adding Juspay MCP to ${selected.length} agent(s)...`)
  for (const a of selected) {
    const sc = scopeFor(a)
    const already = await hasOurMcp(a, sc)
    try {
      await writeMcp(a, sc)
      configured.push(a)
      if (!already) pending.push(a)
    } catch (err) {
      info(`${a.label}: ${(err as Error).message}`)
    }
  }
  s.done(`Configured ${configured.map((a) => a.label).join(", ")}`)
  // Best-effort funnel "setup" milestone per freshly-configured agent (never blocks
  // meaningfully — each call is timeout-bounded and swallows errors). Only the newly
  // added agents (`pending`), so re-running setup doesn't re-emit for existing ones.
  if (pending.length > 0) await Promise.allSettled(pending.map((a) => emitSetupStage(a)))
  if (scope === "project") {
    const forced = configured.filter((a) => a.globalOnly)
    if (forced.length > 0) {
      info(`${forced.map((a) => a.label).join(", ")} only support global scope — configured globally.`)
    }
  }

  // 2. Skills — install per EFFECTIVE scope (global-only agents go to global).
  // Track outcome on the result so the summary + exit code reflect reality
  // (previously a failure here was warned but the box still said "complete").
  let skillsInstalled = true // stays true if there's nothing to install
  let skillsError: string | undefined
  if (configured.length > 0) {
    step("Installing skills...")
    skillsInstalled = false // about to attempt — flip back to true on success
    try {
      for (const sc of ["project", "global"] as const) {
        const group = configured.filter((a) => scopeFor(a) === sc)
        if (group.length > 0) await addSkills(group, sc)
      }
      skillsInstalled = true
      // Per-skill ✓ ticks already convey success, so no redundant "Skills
      // installed" line. But surface the upstream security note exactly once
      // — these skills run with the agent's full permissions.
      warn("Review skills before use — they run with full agent permissions.")
    } catch (err) {
      skillsError = (err as Error).message
      warn(`Skills install failed: ${skillsError}`)
    }
  }

  return { configured, pending, scope, attempted: selected.length, skillsInstalled, skillsError }
}

async function pickAgents(detected: AgentDef[], interactive: boolean): Promise<AgentDef[]> {
  if (!interactive) return detected // CI/headless: configure all detected
  // Clack's multiselect only nags on an empty submit — many users don't realise
  // selection is space, not enter. State it up front.
  hint("space to select · ↑/↓ to move · enter to confirm")
  const ids = await multiselect({
    message: "Which agents should get Juspay MCP + skills?",
    options: detected.map((a) => ({ value: a.id, label: a.label })),
    initialValues: [], // nothing pre-ticked — opt in
    required: true, // can't confirm an empty selection
  })
  if (isCancel(ids)) {
    cancel("Cancelled.")
    process.exit(0)
  }
  const set = new Set(ids as string[])
  return detected.filter((a) => set.has(a.id))
}

async function pickScope(interactive: boolean): Promise<Scope> {
  if (!interactive) return "global" // CI/headless default
  const scope = await select({
    message: "Install where?",
    options: [
      { value: "global", label: "Global", hint: "available in every project" },
      { value: "project", label: "This project", hint: "lives in this repo (committable)" },
    ],
    initialValue: "global",
  })
  if (isCancel(scope)) {
    cancel("Cancelled.")
    process.exit(0)
  }
  return scope as Scope
}

/**
 * Generic MCP config writer/remover, scope-aware. Driven by the agent registry —
 * one code path for every agent, JSON and TOML, global or project scope.
 *
 * We write two URL-only server entries (docs + dashboard) into the agent's config
 * for the chosen scope, preserving everything else. No token is written.
 *
 * Safety: if a config file exists but doesn't parse, we ABORT rather than
 * overwrite — these are real user files (e.g. ~/.claude.json) we must not clobber.
 */

import fs from "node:fs/promises"
import path from "node:path"
import { parse as parseToml, stringify as stringifyToml } from "smol-toml"

import {
  configFileFor,
  DASHBOARD_MCP_NAME,
  DOCS_MCP_ENDPOINT,
  DOCS_MCP_NAME,
  JUSPAY_MCP_ENDPOINT,
  OUR_MCP_NAMES,
  readExisting,
  type AgentDef,
  type Scope,
} from "../../../../shared/agents/index.js"
import { analyticsEnabled, getInstallId, mcpAnalyticsHeaders } from "../../../../shared/analytics/index.js"
import { callMcpTool } from "../../../../shared/auth/mcp-call.js"

// Tag the MCP URL with the durable install id + which agent this config is for, in
// the query string — the durable carrier. Some agents don't forward custom headers
// at all (e.g. older Codex), and TLS-inspecting corporate proxies strip them; the URL
// query always reaches the MCP. `agent` lets the backend attribute a session to the
// client (claude / codex / cursor / …). The header is kept alongside as a secondary path.
export function taggedUrl(url: string, installId?: string, agentId?: string): string {
  if (!installId) return url
  const params = new URLSearchParams({ install_id: installId })
  if (agentId) params.set("agent", agentId)
  const sep = url.includes("?") ? "&" : "?"
  return `${url}${sep}${params.toString()}`
}

// Write our two MCP servers into the agent's config for `scope`.
export async function writeMcp(agent: AgentDef, scope: Scope): Promise<void> {
  const file = configFileFor(agent, scope)
  // Tag both servers with the durable install id (+ agent slug) so the backend can
  // attribute MCP hits to this machine's journey and to the calling agent. Carried in
  // the URL query (primary) AND the header (secondary). Opt-out (analyticsEnabled=false)
  // writes plain URL-only entries as before.
  const installId = analyticsEnabled() ? await getInstallId() : undefined
  const headers = installId ? mcpAnalyticsHeaders(installId) : undefined
  // The DOCS server is unauthenticated, so it ALWAYS carries install_id + agent in the
  // query (the proxy-resilient primary carrier) — this is where the backend gets the
  // machine's session identity and the calling agent, for every agent.
  //
  // The DASHBOARD server is OAuth-protected and its URL is the OAuth *resource
  // identifier* — a query string there breaks the OAuth flow for some clients (VS Code,
  // Antigravity), so those get a canonical dashboard URL (flagged noDashboardQuery).
  // Everyone else keeps the query on the dashboard too (proxy-resilient mid stitching).
  // The dashboard always keeps the install_id header + gets mid from its OAuth session.
  const docsUrl = taggedUrl(DOCS_MCP_ENDPOINT, installId, agent.id)
  const dashUrl = agent.noDashboardQuery
    ? JUSPAY_MCP_ENDPOINT
    : taggedUrl(JUSPAY_MCP_ENDPOINT, installId, agent.id)
  const entries: Record<string, unknown> = {
    [DOCS_MCP_NAME]: agent.entry(docsUrl, headers),
    [DASHBOARD_MCP_NAME]: agent.entry(dashUrl, headers),
  }

  await fs.mkdir(path.dirname(file), { recursive: true })
  if (agent.format === "json") await mergeJson(file, agent.containerKey, entries)
  else await mergeToml(file, agent.containerKey, entries)
}

// Best-effort "setup" funnel milestone: once this machine has configured an agent,
// tell the backend the tooling is in place. This is the truthful top of the funnel —
// it fires at config time, before any skill runs, so "installed but never engaged" is
// visible. The DOCS server is unauthenticated, so we call its (public) tracking tool
// directly with the same tagged URL we just wrote (install_id + agent slug carry the
// identity); no secret ever leaves the CLI — the docs MCP holds the ingest token.
// Telemetry, never a gate: bounded by a short timeout and swallows every error.
export async function emitSetupStage(agent: AgentDef): Promise<void> {
  if (!analyticsEnabled()) return
  let installId: string | undefined
  try {
    installId = await getInstallId()
  } catch {
    return
  }
  if (!installId) return
  const url = taggedUrl(DOCS_MCP_ENDPOINT, installId, agent.id)
  try {
    await withTimeout(
      callMcpTool(url, "", "juspay_track_integration_stage", { phase: "setup", status: "completed" }),
      2000,
    )
  } catch {
    // analytics must never disrupt setup — drop timeouts/network/tool errors silently
  }
}

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("timeout")), ms)
    if (typeof t.unref === "function") t.unref()
    p.then(resolve, reject).finally(() => clearTimeout(t))
  })
}

// Remove our two MCP servers from the agent's config at `scope`. Returns true if
// anything was removed.
export async function removeMcp(agent: AgentDef, scope: Scope): Promise<boolean> {
  const file = configFileFor(agent, scope)
  let raw: string
  try {
    raw = await fs.readFile(file, "utf8")
  } catch {
    return false
  }

  const config = (agent.format === "json" ? JSON.parse(raw) : parseToml(raw)) as Record<string, unknown>
  const container = config[agent.containerKey] as Record<string, unknown> | undefined
  if (!container) return false

  let changed = false
  for (const name of OUR_MCP_NAMES) {
    if (container[name]) {
      delete container[name]
      changed = true
    }
  }
  if (!changed) return false

  const out = agent.format === "json" ? JSON.stringify(config, null, 2) + "\n" : stringifyToml(config)
  await writeAtomic(file, out)
  return true
}

async function mergeJson(file: string, containerKey: string, entries: Record<string, unknown>): Promise<void> {
  const config = (await readExisting(file, "json")) ?? {}
  const container =
    config[containerKey] && typeof config[containerKey] === "object"
      ? (config[containerKey] as Record<string, unknown>)
      : {}
  Object.assign(container, entries)
  config[containerKey] = container
  await writeAtomic(file, JSON.stringify(config, null, 2) + "\n")
}

async function mergeToml(file: string, containerKey: string, entries: Record<string, unknown>): Promise<void> {
  const config = (await readExisting(file, "toml")) ?? {}
  const container =
    config[containerKey] && typeof config[containerKey] === "object"
      ? (config[containerKey] as Record<string, unknown>)
      : {}
  Object.assign(container, entries)
  config[containerKey] = container
  await writeAtomic(file, stringifyToml(config))
}

// Atomic write: tempfile + rename, so a concurrent reader or a crash never
// sees a partial config. Mode 0o600 because agent configs (e.g. ~/.claude.json)
// can hold OAuth state and must not be world-readable. (Borrowed from
// microsoft/apm's adapter conventions.)
async function writeAtomic(file: string, contents: string): Promise<void> {
  const tmp = `${file}.tmp.${process.pid}.${Date.now()}`
  await fs.writeFile(tmp, contents, { mode: 0o600 })
  await fs.rename(tmp, file)
}

/**
 * Skills installation via the `skills` npm CLI (vercel-labs/skills).
 * Driven by OUR selection + scope: `skills add <pkg> [-g] -y -a <slug>` — global
 * (`-g`) or project (default), targeting exactly the agents the user picked. No
 * interactive picker (avoids missed agents + redraw glitches).
 */

import { spawn } from "node:child_process"
import fs from "node:fs/promises"
import os from "node:os"
import path from "node:path"

import { OUR_SKILL_NAMES, SKILLS_PACKAGES, type AgentDef, type Scope } from "../../../../shared/agents/index.js"
import { spin } from "../../../../core/ui.js"

// Re-export so callers (index.ts summary, etc.) can name the installed skills
// without reaching into servers.ts directly.
export { OUR_SKILL_NAMES } from "../../../../shared/agents/index.js"

export async function addSkills(agents: AgentDef[], scope: Scope): Promise<void> {
  const slugs = [...new Set(agents.map((a) => a.skillsSlug).filter((s): s is string => Boolean(s)))]
  if (slugs.length === 0) return
  const base = scope === "global" ? os.homedir() : process.cwd()
  // The `skills` CLI only symlinks the skill into an agent's own dir if that dir
  // already exists — it will NOT create `.claude/` itself. So pre-create Claude's
  // skills dir; then the CLI wires it. (Codex etc. read the auto-created
  // `.agents/skills`, so they need no pre-creation.)
  if (agents.some((a) => a.id === "claude")) {
    await fs.mkdir(path.join(base, ".claude", "skills"), { recursive: true })
  }
  const scopeArgs = scope === "global" ? ["-g"] : []
  const agentArgs = slugs.flatMap((s) => ["-a", s])
  // Install each skill in turn under our own spinner — replaces the upstream
  // `skills` CLI's per-package ASCII banner + clack boxes (which used to print
  // ~30 lines × 3 skills). Atomic-fail: if any throws, the loop bubbles up
  // and setup.ts marks the wizard as partial. runSkills() captures the child's
  // output and dumps it only on failure, so debug detail is preserved.
  for (const pkg of SKILLS_PACKAGES) {
    const name = pkg.split("/").pop() ?? pkg
    const s = spin(`Installing ${name}...`)
    try {
      await runSkills(["add", pkg, ...scopeArgs, "-y", ...agentArgs])
      s.done(name)
    } catch (err) {
      s.fail(name)
      throw err
    }
  }
}

// Best-effort removal from BOTH scopes for every skill. `skills remove` takes
// the skill NAME, not the package path. Keep going past per-skill failures so
// uninstall cleans as much as it can. Returns true if anything was removed.
export async function removeSkills(): Promise<boolean> {
  let removedAny = false
  for (const skill of OUR_SKILL_NAMES) {
    const global = await runSkills(["remove", skill, "-g", "-y"]).then(() => true).catch(() => false)
    const project = await runSkills(["remove", skill, "-y"]).then(() => true).catch(() => false)
    if (global || project) removedAny = true
  }
  return removedAny
}

// When our CLI is itself launched via `npx`/`npm exec`, npm pre-populates the
// child env with `npm_*` vars + INIT_CWD describing the OUTER invocation. A
// nested `npx` then misreads them — `npm_config_prefix` leaks, `npm_command=exec`
// short-circuits, `npm_package_name=juspay` confuses package resolution.
// Strip them so the inner process sees a fresh-shell env.
function scrubbedEnv(): NodeJS.ProcessEnv {
  const env = { ...process.env }
  for (const k of Object.keys(env)) {
    if (k.startsWith("npm_")) delete env[k]
  }
  delete env.INIT_CWD
  return env
}

function runSkills(args: string[]): Promise<void> {
  return new Promise((resolve, reject) => {
    // `npm exec --yes --package skills -- skills <args>` is the canonical,
    // unambiguous shape of `npx -y skills <args>`. Spelling out `--package`
    // and `--` keeps newer npm argv parsers happy and survives nesting under
    // an outer `npx`. Windows: npm is npm.cmd; spawn needs a shell for .cmd.
    //
    // stdio: stdin /dev/null (we pass -y, no prompts), stdout+stderr piped so
    // we can render our own concise progress upstream and only surface the
    // child's verbose output if something fails.
    const child = spawn(
      "npm",
      ["exec", "--yes", "--package", "skills", "--", "skills", ...args],
      { stdio: ["ignore", "pipe", "pipe"], shell: process.platform === "win32", env: scrubbedEnv() },
    )
    const buf: Buffer[] = []
    child.stdout?.on("data", (d) => buf.push(d as Buffer))
    child.stderr?.on("data", (d) => buf.push(d as Buffer))
    child.on("error", reject)
    child.on("exit", (code) => {
      if (code === 0) return resolve()
      // Failure path: dump the child's full output verbatim so the user
      // (and CI logs) still see exactly what the `skills` CLI would have said.
      const out = Buffer.concat(buf).toString("utf8")
      if (out) process.stderr.write(out.endsWith("\n") ? out : out + "\n")
      reject(new Error(`skills ${args[0]} exited ${code}`))
    })
  })
}

