/**
 * Session orchestration — the `acquireTokens()` / merchant-details logic ported
 * from juspay-skills/claude-cli/src/init.ts, plus the `ensureAuth()` gate the
 * wrapper plan (§5.1) calls first.
 *
 * Validity & refresh match the shipped behaviour exactly (plan §6.4): a token is
 * usable only if it expires >24h out; otherwise we re-run the full browser flow.
 * There is no silent refresh-token exchange yet (the refresh_token is stored but
 * unused) — that's a deliberate v1 port-as-is, not an oversight.
 */

import { JUSPAY_MCP_ENDPOINT, JUSPAY_MCP_ISSUER } from "./constants.js"
import { callMcpTool } from "./mcp-call.js"
import { runOAuthFlow } from "./oauth.js"
import {
  clearStore,
  readConfig,
  readOAuth,
  writeConfig,
  writeOAuth,
  type Config,
  type Environment,
  type OAuthState,
} from "./store.js"
import { done, spin, step } from "../../core/ui.js"

export type Identity = {
  merchant_id: string
  environment: Environment
  expires_at: number
}

// The auth gate: return a valid token + identity, running the browser flow only
// if there isn't already a token valid >24h out. Everything downstream (provision,
// launch) gets its bearer from here.
export async function ensureAuth(opts: { env?: Environment; force?: boolean } = {}): Promise<{
  tokens: OAuthState
  identity: Identity
}> {
  const { tokens, fresh } = await acquireTokens({ force: opts.force ?? false })
  const expiresOn = new Date(tokens.expires_at * 1000).toDateString()
  done(`Signed in · session valid until ${expiresOn}`)

  // Reuse cached merchant metadata ONLY when we reused an existing token. A freshly
  // acquired token (forced re-auth, or re-auth after expiry) may belong to a
  // different merchant, so the on-disk config.json could be stale — re-resolve.
  if (!fresh) {
    const cached = await readConfig().catch(() => null)
    if (cached) {
      return { tokens, identity: toIdentity(cached, tokens) }
    }
  }

  const config = await resolveMerchant(tokens.access_token, opts.env ?? "production")
  await writeConfig(config)
  return { tokens, identity: toIdentity(config, tokens) }
}

// Return a usable access token, or null if not signed in / expired. Does NOT
// trigger the browser flow — callers that want that use ensureAuth().
export async function getToken(): Promise<string | null> {
  const existing = await readOAuth().catch(() => null)
  if (existing && isStillValid(existing)) return existing.access_token
  return null
}

// `juspay checkout auth whoami` — show the current identity, or null if signed out.
export async function whoami(): Promise<Identity | null> {
  const tokens = await readOAuth().catch(() => null)
  if (!tokens || !isStillValid(tokens)) return null
  const config = await readConfig().catch(() => null)
  if (config) return toIdentity(config, tokens)

  // Token but no cached merchant metadata — fetch it once and cache.
  const resolved = await resolveMerchant(tokens.access_token, "production")
  await writeConfig(resolved)
  return toIdentity(resolved, tokens)
}

export type LogoutResult = { revoked: boolean }

// `juspay checkout auth logout` — drop local creds and best-effort server-side
// revoke. Returns whether the revoke call succeeded so the caller can report it.
export async function logout(): Promise<LogoutResult> {
  const tokens = await readOAuth().catch(() => null)
  await clearStore()
  if (!tokens) return { revoked: false }
  return { revoked: await revokeQuietly(tokens) }
}

// Returns the usable token plus whether it was freshly acquired (so the caller
// knows the cached merchant metadata can't be trusted).
async function acquireTokens(opts: { force: boolean }): Promise<{ tokens: OAuthState; fresh: boolean }> {
  const previous = await readOAuth().catch(() => null)
  if (!opts.force && previous && isStillValid(previous)) {
    return { tokens: previous, fresh: false }
  }

  step("Opening browser for sign-in...")
  const fresh = await runOAuthFlow(JUSPAY_MCP_ISSUER)
  await writeOAuth(fresh)
  // We just overwrote an existing credential on disk — revoke the OLD token
  // server-side (best-effort) so a forced/expired re-auth doesn't leave the
  // previous session dangling as a still-valid credential.
  if (previous) await revokeQuietly(previous)
  return { tokens: fresh, fresh: true }
}

// Treat tokens expiring in <24h as already expired — avoids handing the merchant
// a session that's about to die mid-integration.
function isStillValid(state: OAuthState): boolean {
  const skewSeconds = 24 * 60 * 60
  return state.expires_at > Math.floor(Date.now() / 1000) + skewSeconds
}

function toIdentity(config: Config, tokens: OAuthState): Identity {
  return { merchant_id: config.merchant_id, environment: config.environment, expires_at: tokens.expires_at }
}

async function resolveMerchant(bearer: string, env: Environment): Promise<Config> {
  const s = spin("Fetching merchant details...")
  let merchantId: string
  try {
    merchantId = await fetchMerchantId(bearer)
  } catch (err) {
    s.fail("Could not fetch merchant details")
    throw err
  }
  s.done(`Merchant: ${merchantId}`)
  return { merchant_id: merchantId, client_id: merchantId, environment: env }
}

async function fetchMerchantId(bearer: string): Promise<string> {
  const result = await callMcpTool(JUSPAY_MCP_ENDPOINT, bearer, "juspay_get_merchant_details", {})
  const merchantId = extractMerchantId(result)
  if (!merchantId) {
    throw new Error(
      "Could not find merchantId in juspay_get_merchant_details response. " +
        "Report this issue if it persists.",
    )
  }
  return merchantId
}

function extractMerchantId(result: unknown): string | undefined {
  if (!result || typeof result !== "object") return undefined
  const r = result as Record<string, unknown>

  if (typeof r.merchantId === "string") return r.merchantId

  if (r.structuredContent && typeof r.structuredContent === "object") {
    const sc = r.structuredContent as Record<string, unknown>
    if (typeof sc.merchantId === "string") return sc.merchantId
  }

  if (Array.isArray(r.content)) {
    for (const item of r.content) {
      if (item && typeof item === "object") {
        const it = item as Record<string, unknown>
        if (it.type === "text" && typeof it.text === "string") {
          try {
            const parsed = JSON.parse(it.text) as Record<string, unknown>
            if (typeof parsed.merchantId === "string") return parsed.merchantId
          } catch {
            // not JSON; ignore
          }
        }
      }
    }
  }

  return undefined
}

// Best-effort server-side revoke (§13). The dashboard issuer advertises a
// revocation_endpoint; if it's reachable we revoke, but logout never fails on it
// — the local creds are already gone by the time we get here. Returns true if the
// revoke endpoint accepted our request.
//
// We revoke the refresh_token first: per RFC 7009 revoking a refresh token kills
// the whole grant (and the access tokens issued under it), so it's the complete
// teardown. We also revoke the access_token explicitly as belt-and-suspenders.
async function revokeQuietly(tokens: OAuthState): Promise<boolean> {
  try {
    const meta = await fetch(
      tokens.issuer.replace(/\/$/, "") + "/.well-known/oauth-authorization-server",
      { headers: { Accept: "application/json" } },
    ).then((r) => (r.ok ? (r.json() as Promise<{ revocation_endpoint?: string }>) : null))
    if (!meta?.revocation_endpoint) return false

    const revoke = (token: string, hint: "refresh_token" | "access_token") =>
      fetch(meta.revocation_endpoint!, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          token,
          token_type_hint: hint,
          client_id: tokens.client_id,
          client_secret: tokens.client_secret,
        }).toString(),
      }).then((r) => r.ok)

    // RFC 7009 servers return 200 even for an already-invalid token, so an ok
    // response on the refresh-token revoke is our success signal.
    const refreshOk = await revoke(tokens.refresh_token, "refresh_token")
    await revoke(tokens.access_token, "access_token").catch(() => false)
    return refreshOk
  } catch {
    // best-effort; logout already cleared local state
    return false
  }
}

/**
 * On-disk credential store under ~/.config/juspay/ — ports oauth-config.ts +
 * config.ts from juspay-skills/claude-cli/src into one module, with the
 * carry-over hardening the wrapper plan calls for (§6.2 / §13):
 *   - the directory is created 0700 (the original left it at the umask default),
 *   - files are written atomically (tmp + rename, as in agent-setup/mcp-writer.ts)
 *     at mode 0600,
 *   - on read we refuse to proceed if perms are unexpectedly world/group-readable
 *     rather than silently trusting an over-open token file.
 *
 * Two files, matching the shipped shapes:
 *   oauth.json   — the TokenSet (issuer, client creds, tokens, expiry, scope)
 *   config.json  — merchant metadata (merchant_id, client_id, environment)
 */

import fs from "node:fs/promises"
import path from "node:path"

import { juspayConfigDir, juspayConfigPath, juspayOauthPath } from "./paths.js"
import type { TokenSet } from "./oauth.js"

// The stored OAuth shape is exactly the TokenSet returned by the flow.
export type OAuthState = TokenSet

export type Environment = "sandbox" | "production"

export type Config = {
  merchant_id: string
  client_id: string
  environment: Environment
}

export async function readOAuth(): Promise<OAuthState | null> {
  const raw = await readSecure(juspayOauthPath)
  if (raw === null) return null
  const parsed = JSON.parse(raw) as unknown
  if (!isOAuthState(parsed)) {
    throw new Error(
      `Invalid OAuth state at ${juspayOauthPath}. Re-run \`juspay checkout auth login\` to recreate.`,
    )
  }
  return parsed
}

export async function writeOAuth(state: OAuthState): Promise<void> {
  await ensureDir()
  await writeAtomic(juspayOauthPath, JSON.stringify(state, null, 2) + "\n")
}

export async function readConfig(): Promise<Config | null> {
  const raw = await readSecure(juspayConfigPath)
  if (raw === null) return null
  const parsed = JSON.parse(raw) as unknown
  if (!isConfig(parsed)) {
    throw new Error(
      `Invalid config at ${juspayConfigPath}. Expected { merchant_id, client_id, environment }. ` +
        `Re-run \`juspay checkout auth login\` to recreate.`,
    )
  }
  return parsed
}

export async function writeConfig(config: Config): Promise<void> {
  await ensureDir()
  await writeAtomic(juspayConfigPath, JSON.stringify(config, null, 2) + "\n")
}

// Logout: remove the whole credential dir (both files). Best-effort — absent
// files are not an error.
export async function clearStore(): Promise<void> {
  await fs.rm(juspayConfigDir, { recursive: true, force: true })
}

// Create the config dir at 0700 (owner-only). mkdir's `mode` is masked by the
// umask, so chmod afterwards to guarantee the bits regardless of umask.
async function ensureDir(): Promise<void> {
  await fs.mkdir(juspayConfigDir, { recursive: true, mode: 0o700 })
  if (process.platform !== "win32") {
    await fs.chmod(juspayConfigDir, 0o700).catch(() => {})
  }
}

// Read a credential file, or null if absent. Refuses (throws) if the file's
// perms are broader than owner-only — we don't silently weaken (§13).
async function readSecure(file: string): Promise<string | null> {
  let stat: import("node:fs").Stats
  try {
    stat = await fs.stat(file)
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return null
    throw err
  }
  if (process.platform !== "win32" && (stat.mode & 0o077) !== 0) {
    throw new Error(
      `${file} is readable by group/others (mode ${(stat.mode & 0o777).toString(8)}). ` +
        `Fix with \`chmod 600 ${file}\` (and \`chmod 700 ${juspayConfigDir}\`), then re-run.`,
    )
  }
  return fs.readFile(file, "utf8")
}

// Atomic write at 0600: tmp file + rename, so a crash or concurrent reader never
// sees a partial token file. (Same convention as agent-setup/mcp-writer.ts.)
async function writeAtomic(file: string, contents: string): Promise<void> {
  const tmp = `${file}.tmp.${process.pid}.${Date.now()}`
  await fs.writeFile(tmp, contents, { mode: 0o600 })
  if (process.platform !== "win32") {
    await fs.chmod(tmp, 0o600).catch(() => {})
  }
  await fs.rename(tmp, file)
}

function isOAuthState(value: unknown): value is OAuthState {
  if (!value || typeof value !== "object") return false
  const v = value as Record<string, unknown>
  return (
    typeof v.issuer === "string" &&
    typeof v.client_id === "string" &&
    typeof v.client_secret === "string" &&
    typeof v.access_token === "string" &&
    typeof v.refresh_token === "string" &&
    typeof v.expires_at === "number" &&
    typeof v.scope === "string"
  )
}

function isConfig(value: unknown): value is Config {
  if (!value || typeof value !== "object") return false
  const v = value as Record<string, unknown>
  return (
    typeof v.merchant_id === "string" &&
    v.merchant_id.length > 0 &&
    typeof v.client_id === "string" &&
    v.client_id.length > 0 &&
    (v.environment === "sandbox" || v.environment === "production")
  )
}

/**
 * Where Juspay's own credentials live — XDG-aware, NOT the shell rc (see the
 * wrapper plan §6.2). Ported from juspay-skills/claude-cli/src/paths.ts, trimmed
 * to just the auth locations this layer owns.
 *
 *   ~/.config/juspay/oauth.json   — the OAuth token set (0600, in a 0700 dir)
 *   ~/.config/juspay/config.json  — merchant metadata (0600)
 *
 * `XDG_CONFIG_HOME` is honoured so this matches gh / aws / gcloud / stripe.
 */

import os from "node:os"
import path from "node:path"

function xdgConfigHome(): string {
  return process.env.XDG_CONFIG_HOME || path.join(os.homedir(), ".config")
}

export const juspayConfigDir = path.join(xdgConfigHome(), "juspay")
export const juspayConfigPath = path.join(juspayConfigDir, "config.json")
export const juspayOauthPath = path.join(juspayConfigDir, "oauth.json")

/**
 * Dashboard OAuth — DCR + PKCE + loopback. Ported from
 * juspay-skills/claude-cli/src/oauth.ts (the shipped, production flow), adjusted
 * for this CLI: imports the User-Agent from ./constants, client_name + error
 * hints reference `juspay checkout auth login`.
 *
 * This runs the same OAuth the Juspay dashboard MCP uses, so the token is a real
 * dashboard credential (reused for `whoami` and as the model gateway apiKey).
 */

import { spawn } from "node:child_process"
import crypto from "node:crypto"
import http from "node:http"

import pc from "picocolors"

import { USER_AGENT } from "./constants.js"

const REDIRECT_PORT = 33418
const REDIRECT_URI = `http://localhost:${REDIRECT_PORT}/callback`
const OAUTH_TIMEOUT_MS = 5 * 60 * 1000 // 5 minutes

const SCOPES = [
  "analytics:read",
  "orders:read",
  "orders:write",
  "settings:read",
  "gateways:read",
  "reports:read",
  "users:read",
  "alerts:read",
].join(" ")

export type TokenSet = {
  issuer: string
  client_id: string
  client_secret: string
  access_token: string
  refresh_token: string
  expires_at: number
  scope: string
}

type AuthServerMeta = {
  authorization_endpoint: string
  token_endpoint: string
  registration_endpoint: string
}

type DcrResponse = {
  client_id: string
  client_secret: string
}

type TokenResponse = {
  access_token: string
  refresh_token: string
  expires_in: number
  scope?: string
  token_type: string
}

export async function runOAuthFlow(issuer: string): Promise<TokenSet> {
  const meta = await discover(issuer)
  const dcr = await registerClient(meta.registration_endpoint)
  const verifier = base64url(crypto.randomBytes(32))
  const challenge = base64url(crypto.createHash("sha256").update(verifier).digest())
  const state = base64url(crypto.randomBytes(16))

  const { code, returnedState } = await captureCode((codeUrl) => {
    const authUrl =
      meta.authorization_endpoint +
      "?" +
      new URLSearchParams({
        response_type: "code",
        client_id: dcr.client_id,
        redirect_uri: REDIRECT_URI,
        scope: SCOPES,
        state,
        code_challenge: challenge,
        code_challenge_method: "S256",
      }).toString()
    process.stdout.write("  " + pc.dim(`If the browser doesn't open: ${authUrl}\n`))
    openBrowser(authUrl)
    return codeUrl
  })

  if (returnedState !== state) {
    throw new Error("OAuth state mismatch — aborting.")
  }

  const tok = await exchangeCode({
    tokenEndpoint: meta.token_endpoint,
    code,
    verifier,
    clientId: dcr.client_id,
    clientSecret: dcr.client_secret,
  })

  const issuedAt = Math.floor(Date.now() / 1000)
  return {
    issuer,
    client_id: dcr.client_id,
    client_secret: dcr.client_secret,
    access_token: tok.access_token,
    refresh_token: tok.refresh_token,
    expires_at: issuedAt + tok.expires_in,
    scope: tok.scope ?? SCOPES,
  }
}

async function discover(issuer: string): Promise<AuthServerMeta> {
  const url = issuer.replace(/\/$/, "") + "/.well-known/oauth-authorization-server"
  const r = await fetchJson(url)
  if (!r.authorization_endpoint || !r.token_endpoint || !r.registration_endpoint) {
    throw new Error(`Auth server metadata at ${url} is missing required endpoints.`)
  }
  return r as AuthServerMeta
}

async function registerClient(registrationEndpoint: string): Promise<DcrResponse> {
  const body = {
    client_name: "juspay-cli",
    redirect_uris: [REDIRECT_URI],
    grant_types: ["authorization_code", "refresh_token"],
    response_types: ["code"],
    scope: SCOPES,
  }
  const r = await fetchJson(registrationEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  })
  if (!r.client_id || !r.client_secret) {
    throw new Error("Dynamic client registration did not return client_id/client_secret.")
  }
  return r as DcrResponse
}

async function exchangeCode(params: {
  tokenEndpoint: string
  code: string
  verifier: string
  clientId: string
  clientSecret: string
}): Promise<TokenResponse> {
  const form = new URLSearchParams({
    grant_type: "authorization_code",
    code: params.code,
    redirect_uri: REDIRECT_URI,
    client_id: params.clientId,
    client_secret: params.clientSecret,
    code_verifier: params.verifier,
  })
  const r = await fetchJson(params.tokenEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: form.toString(),
  })
  if (!r.access_token || !r.refresh_token || typeof r.expires_in !== "number") {
    throw new Error("Token endpoint did not return access_token/refresh_token/expires_in.")
  }
  return r as TokenResponse
}

function captureCode(
  startBrowser: (codeUrl: string) => void,
): Promise<{ code: string; returnedState: string }> {
  return new Promise((resolve, reject) => {
    let timer: NodeJS.Timeout | null = null
    const cleanup = () => {
      if (timer) clearTimeout(timer)
      server.close()
    }

    const server = http.createServer((req, res) => {
      if (!req.url) return
      const u = new URL(req.url, REDIRECT_URI)
      if (u.pathname !== "/callback") {
        res.writeHead(404)
        res.end()
        return
      }
      const code = u.searchParams.get("code")
      const returnedState = u.searchParams.get("state") ?? ""
      const error = u.searchParams.get("error")
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" })
      if (error) {
        res.end(`<h2>Sign-in failed: ${escapeHtml(error)}</h2><p>You can close this tab.</p>`)
        cleanup()
        reject(new Error(`OAuth error from authorization server: ${error}`))
        return
      }
      if (!code) {
        res.end("<h2>Missing code.</h2><p>You can close this tab.</p>")
        cleanup()
        reject(new Error("Authorization server callback was missing the code parameter."))
        return
      }
      res.end(
        "<h2>Signed in successfully.</h2><p>You can close this tab and return to the terminal.</p>",
      )
      cleanup()
      resolve({ code, returnedState })
    })
    server.on("error", (err: NodeJS.ErrnoException) => {
      cleanup()
      if (err.code === "EADDRINUSE") {
        reject(
          new Error(
            `Port ${REDIRECT_PORT} is already in use. Close whatever is using it and re-run \`juspay checkout auth login\`.`,
          ),
        )
      } else {
        reject(err)
      }
    })
    server.listen(REDIRECT_PORT, "127.0.0.1", () => {
      startBrowser(REDIRECT_URI)
      timer = setTimeout(() => {
        cleanup()
        reject(
          new Error(
            `Sign-in timed out after ${OAUTH_TIMEOUT_MS / 60000} minutes. Re-run \`juspay checkout auth login\` to retry.`,
          ),
        )
      }, OAUTH_TIMEOUT_MS)
    })
  })
}

function openBrowser(url: string): void {
  // Open the URL with NO shell, passing it as a single argument so query-string
  // characters survive intact. On Windows we must NOT use the cmd.exe `start`
  // builtin: cmd splits the URL at `&` (command separator) and mangles `%xx`
  // percent-encoding, so the browser would get a truncated authorize URL with no
  // redirect_uri (→ "redirect_uri is required"). rundll32 receives the URL as one
  // verbatim argv entry and hands it to the default browser unmodified.
  let cmd: string
  let args: string[]
  if (process.platform === "darwin") {
    cmd = "open"
    args = [url]
  } else if (process.platform === "win32") {
    cmd = "rundll32"
    args = ["url.dll,FileProtocolHandler", url]
  } else {
    cmd = "xdg-open"
    args = [url]
  }
  spawn(cmd, args, { stdio: "ignore", detached: true }).unref()
}

async function fetchJson(url: string, init?: RequestInit): Promise<any> {
  let res: Response
  try {
    res = await fetch(url, {
      ...init,
      headers: {
        Accept: "application/json",
        "User-Agent": USER_AGENT,
        ...(init?.headers ?? {}),
      },
    })
  } catch (err) {
    // Node's fetch throws `fetch failed` with the real reason buried in `cause`.
    // Surface enough detail to diagnose proxy / DNS / TLS / refused issues.
    const cause = (err as { cause?: { code?: string; message?: string } }).cause
    const detail = cause?.code ? `${cause.code}${cause.message ? ` — ${cause.message}` : ""}` : (err as Error).message
    throw new Error(`Could not reach ${url}\n  ${detail}`)
  }
  if (!res.ok) {
    const text = await res.text().catch(() => "")
    throw new Error(`HTTP ${res.status} from ${url}${text ? `: ${text.slice(0, 300)}` : ""}`)
  }
  return res.json()
}

function base64url(buf: Buffer): string {
  return buf.toString("base64").replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_")
}

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) =>
    c === "&"
      ? "&amp;"
      : c === "<"
        ? "&lt;"
        : c === ">"
          ? "&gt;"
          : c === '"'
            ? "&quot;"
            : "&#39;",
  )
}

