export function findAgent(id: string): AgentDef | undefined {
  return AGENTS.find((a) => a.id === id)
}

// The config file for an agent at a given scope (project = relative to cwd).
export function configFileFor(agent: AgentDef, scope: Scope): string {
  return scope === "global" ? agent.globalPath : path.join(process.cwd(), agent.projectPath)
}

// Which agents to configure: any detected as installed/used on this machine.
export async function detectAgents(): Promise<AgentDef[]> {
  const out: AgentDef[] = []
  for (const a of AGENTS) {
    if (await isDetected(a)) out.push(a)
  }
  return out
}

async function isDetected(a: AgentDef): Promise<boolean> {
  if (a.bin && (await onPath(a.bin))) return true
  for (const m of a.homeMarkers ?? []) {
    if (await exists(path.join(HOME, m))) return true
  }
  if (a.vscodeExt && (await hasVscode())) return true
  return false
}

async function onPath(bin: string): Promise<boolean> {
  try {
    await which(bin)
    return true
  } catch {
    return false
  }
}

// VS Code is present iff its user-data dir exists (created on first run; the same dir we
// write mcp.json into) — reliable on every OS incl. Windows (%APPDATA%\Code\User), and
// independent of Copilot being built-in (no github.copilot* under ~/.vscode/extensions)
// or `code` being on PATH. The latter two are best-effort fallbacks for edge setups.
async function hasVscode(): Promise<boolean> {
  if (await exists(vscodeUserDir())) return true
  if (await onPath("code")) return true
  return hasVscodeCopilot()
}

async function hasVscodeCopilot(): Promise<boolean> {
  const roots = [path.join(HOME, ".vscode", "extensions"), path.join(HOME, ".vscode-insiders", "extensions")]
  for (const root of roots) {
    try {
      const entries = await fs.readdir(root)
      if (entries.some((e) => e.toLowerCase().startsWith("github.copilot"))) return true
    } catch {
      // dir not present
    }
  }
  return false
}

async function exists(p: string): Promise<boolean> {
  try {
    await fs.access(p)
    return true
  } catch {
    return false
  }
}

/**
 * Agent config READ-side — shared between agent-setup's writer (parsing before a
 * merge) and `juspay launch` (checking whether an agent is Juspay-configured). The
 * WRITE side (writeMcp / removeMcp) stays in agent-setup; this module is read-only.
 */

import fs from "node:fs/promises"

import { parse as parseToml } from "smol-toml"

import { configFileFor, type AgentDef, type Scope } from "./registry.js"
import { DASHBOARD_MCP_NAME } from "./servers.js"

// Read an existing config, or null if absent. Throws (refusing to let a caller
// overwrite) if the file exists but can't be parsed.
export async function readExisting(
  file: string,
  format: AgentDef["format"],
): Promise<Record<string, unknown> | null> {
  let raw: string
  try {
    raw = await fs.readFile(file, "utf8")
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return null
    throw err
  }
  if (raw.trim() === "") return null
  try {
    return (format === "json" ? JSON.parse(raw) : parseToml(raw)) as Record<string, unknown>
  } catch {
    throw new Error(`${file} isn't valid ${format.toUpperCase()}; refusing to overwrite it. Fix or remove it, then re-run.`)
  }
}

// Is OUR dashboard MCP actually in the agent's config at this scope? Reads the real
// container key instead of grepping the raw file, so an unrelated "juspay-mcp"
// mention (in a comment, in another value) doesn't false-positive.
export async function hasOurMcp(agent: AgentDef, scope: Scope): Promise<boolean> {
  const config = await readExisting(configFileFor(agent, scope), agent.format).catch(() => null)
  if (!config) return false
  const container = config[agent.containerKey] as Record<string, unknown> | undefined
  return Boolean(container && container[DASHBOARD_MCP_NAME])
}

